/**
 * 改造自 shadcn 原装 base-lyra popover（https://ui.shadcn.com/r/styles/base-lyra/popover.json，MIT）。
 * 与上游的差异：动效改由 `motion` 属性选预设（ADR 0021）。`Popover` 收 `motion`，经 context 交给
 * `PopoverContent`，弹层渲染 `data-motion`。删掉弹层上的 tw-animate-css 类（`duration-100`、`data-open:animate-in`、
 * `fade-*`、`zoom-*`、`slide-in-from-*`）与 `origin-(--transform-origin)`：预设自己读 Base UI 的 `--transform-origin`。
 * 上游的 100ms 淡入加缩放 95% 保留为预设 `zoom`。此外只有格式化，其余类名逐字保留。
 */
"use client";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";
import { cn } from "cn";
import { type ComponentProps, createContext, use } from "react";

/**
 * 浮层支持的动效预设（ADR 0021）。缺省 `pop`。
 * - `pop`：从触发器一侧淡入加缩放 96%→100%，200ms。
 * - `fade`：只淡入淡出，150ms。
 * - `zoom`：Lyra 原版，淡入加缩放 95%，100ms。
 */
type PopoverMotion = "fade" | "pop" | "zoom";

const PopoverMotionContext = createContext<PopoverMotion>("pop");

function Popover({
  motion = "pop",
  ...props
}: PopoverPrimitive.Root.Props & { motion?: PopoverMotion }) {
  return (
    <PopoverMotionContext value={motion}>
      <PopoverPrimitive.Root data-slot="popover" {...props} />
    </PopoverMotionContext>
  );
}

function PopoverTrigger({ ...props }: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />;
}

function PopoverContent({
  className,
  align = "center",
  alignOffset = 0,
  side = "bottom",
  sideOffset = 4,
  ...props
}: PopoverPrimitive.Popup.Props &
  Pick<PopoverPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">) {
  const motion = use(PopoverMotionContext);
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        className="isolate z-50"
      >
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          data-motion={motion}
          className={cn(
            "z-50 flex w-72 flex-col gap-2.5 rounded-none bg-popover p-2.5 text-xs text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-hidden",
            className,
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  );
}

function PopoverHeader({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      data-slot="popover-header"
      className={cn("flex flex-col gap-1 text-xs", className)}
      {...props}
    />
  );
}

function PopoverTitle({ className, ...props }: PopoverPrimitive.Title.Props) {
  return (
    <PopoverPrimitive.Title
      data-slot="popover-title"
      className={cn("text-sm font-medium", className)}
      {...props}
    />
  );
}

function PopoverDescription({ className, ...props }: PopoverPrimitive.Description.Props) {
  return (
    <PopoverPrimitive.Description
      data-slot="popover-description"
      className={cn("text-xs/relaxed text-muted-foreground", className)}
      {...props}
    />
  );
}

export {
  Popover,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  type PopoverMotion,
  PopoverTitle,
  PopoverTrigger,
};
